// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_stockDutyExerSubmit, tx_fn_openAdjReqWin) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.stockDutyarr = undefined; try { scwin.stockDutyarr = /* sdd-asis-lifecycle:begin stockDutyarr — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05104' }); }

scwin.stockDutyExerarr = undefined; try { scwin.stockDutyExerarr = /* sdd-asis-lifecycle:begin stockDutyExerarr — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05104' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05104.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_stockDutyExerList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_stockDutyExerList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stockDutyExerList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_stockDutyExerList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if ((r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '30')) { if (typeof scwin.openStockDutyExerWin === 'function') { await scwin.openStockDutyExerWin(r["bzProcsNo"], r["follwBzProcsNo"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.openStockDutyExerWin (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openStockDutyExerWin'); } return; }
        if (r["listProcsStatCd"] === '35') { if (typeof scwin.openStockDutyExerWin === 'function') { await scwin.openStockDutyExerWin(r["bzProcsNo"], r["follwBzProcsNo"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.openStockDutyExerWin (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openStockDutyExerWin'); } return; }
        if (r["listProcsStatCd"] === '37') { if (typeof scwin.openStockDutyExerWin === 'function') { await scwin.openStockDutyExerWin(r["bzProcsNo"], r["follwBzProcsNo"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.openStockDutyExerWin (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openStockDutyExerWin'); } return; }
        if (r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '30' ||r["listProcsStatCd"] === '35' ||r["listProcsStatCd"] === '37') { if (typeof scwin.stockDutyExerSubmit === 'function') { await scwin.stockDutyExerSubmit(r["follwBzProcsNo"], r["prtdepoId"], "32"); } else { console.error('[sdd] 행 동작 미정의: scwin.stockDutyExerSubmit (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.stockDutyExerSubmit'); } return; }
        if (r["listProcsStatCd"] === '33') { if (typeof scwin.openAdjReqWin === 'function') { await scwin.openAdjReqWin(r["follwBzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.openAdjReqWin (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openAdjReqWin'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_stockDutyExerList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_openStockDutyExerWin_7_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_openStockDutyExerWin_7_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_openStockDutyExerWin_7_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.openStockDutyExerWin('','','')
        /* sdd-asis-lifecycle:end */

